window.SEARCH_INDEX = [{"p":"architecture.html","a":"why-regulate","t":"為什麼需要穩壓","s":"負載電流會在幾奈秒內從微安跳到數安培，輸入電壓會隨電池放電、充電器插拔或引擎啟動而變化。穩壓器是一個負回授系統：量測輸出、和參考電壓比較，再調整傳輸元件，讓輸出維持在設定值。評估一顆穩壓器，看的就是它在這些擾動下輸出偏了多少、多久回來、花了多少能量。 擾動對應規格典型量級 負載電流緩慢變化負載調節率（load regulation）0.1–1 %/A 輸入電壓緩慢變化線性調節率（line regulation）0.01–0.1 %/V 負載電流快速跳變負載暫態（load tr","g":"arch","lv":1},{"p":"architecture.html","a":"linear-vs-switching","t":"線性穩壓 vs 切換式穩壓","s":"線性穩壓器讓傳輸元件工作在飽和 / 線性區，相當於一個由回授控制的可變電阻。多出來的電壓 (VIN − VOUT) 乘上電流，全部變成熱。好處是簡單、安靜、反應快、沒有電感。 切換式穩壓器讓開關只在完全導通或完全截止兩種狀態間切換，理想情況下開關本身不消耗功率，再用電感與電容把脈衝濾成直流。效率高，但有切換漣波、EMI，外部元件也多。 ηLDO = (VOUT·IOUT) / (VIN·(IOUT + IQ)) ≈ VOUT / VIN 從 3.6 V 降到 1.8 V，LD","g":"arch","lv":1},{"p":"architecture.html","a":"ldo-block","t":"LDO 方塊圖","s":"參考電壓：通常是帶隙（bandgap），溫度係數 < 50 ppm/°C，決定輸出的精度。 誤差放大器：增益決定調節率，頻寬決定暫態，輸出擺幅決定能不能把傳輸元件完全打開（影響壓差）。 傳輸元件：大尺寸 PMOS 或 NMOS，面積可能佔整顆 LDO 的一半以上，閘極電容也最大。 回授分壓：決定輸出電壓；固定輸出版本直接做在晶片內，可調版本把 FB 腳拉出來。 保護電路：限流、熱關機、欠壓鎖定（UVLO）、軟啟動、主動放電，詳見設計 · 保護電路。","g":"arch","lv":1},{"p":"architecture.html","a":"pass-device","t":"傳輸元件：PMOS、NMOS 還是 PNP","s":"傳輸元件最小壓差閘極驅動迴路特性典型用途 PMOS（共源極）I·RDS(on)，可到 50–200 mV拉低閘極即可，無需高於 VIN輸出阻抗高，主極點在輸出，需靠 COUT / ESR 穩定通用 LDO，手機、IoT NMOS（源極隨耦）需 VGS，除非有偏壓軌或電荷泵閘極要高於 VOUT + VGS，需 VBIAS 或內建電荷泵輸出阻抗低（≈1/gm），暫態好、PSRR 高、易穩定低電壓大電流（0.8 V / 3 A）、SoC 核心 PNP（傳統）VCE(sat) ≈ 0","g":"arch","lv":1},{"p":"architecture.html","a":"dropout","t":"壓差、效率與功耗","s":"壓差（dropout voltage, VDO）是輸出開始跟不上設定值時的最小 VIN − VOUT，通常定義在輸出掉 1–2% 或 100 mV 的點。PMOS LDO 進入壓差區時，傳輸元件完全打開，等同一顆電阻： VDO ≈ IOUT · RDS(on) PD = (VIN − VOUT)·IOUT + VIN·IQ TJ = TA + PD·θJA 例：5 V 降 3.3 V、500 mA，PD = 0.85 W。SOT-23 的 θJA 約 200 °C/W，會升溫","g":"arch","lv":1},{"p":"architecture.html","a":"ldo-specs","t":"LDO 關鍵規格","s":"","g":"arch","lv":1},{"p":"architecture.html","a":"ldo-specs","t":"輸出精度","s":"包含參考、分壓電阻、EA 偏移、溫度、線性 / 負載調節的總和，常見 ±1%（25 °C）或 ±2%（全溫）。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"靜態電流 IQ","s":"無負載時 LDO 自己消耗的電流。穿戴與 IoT 要 < 1 µA，高 PSRR、高頻寬的 LDO 可能要數十到數百 µA。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"接地電流 IGND","s":"有負載時流到地的電流，PMOS LDO 接近 IQ，PNP LDO 會隨負載增加。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"關斷電流 ISD","s":"EN 拉低時的漏電，決定待機時電池壽命，常見 < 100 nA。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"PSRR","s":"輸入漣波被抑制的程度，以 dB 表示，隨頻率下降。詳見設計 · PSRR。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"輸出雜訊","s":"10 Hz–100 kHz 的積分雜訊，以 µVRMS 表示。低雜訊 LDO 可達 < 5 µVRMS。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"穩定電容範圍","s":"規格書列出的 COUT 最小值與 ESR 範圍。超出範圍可能振盪，這是最常見的應用問題。","g":"arch","lv":3},{"p":"architecture.html","a":"ldo-specs","t":"限流 / 短路電流","s":"輸出短路時的最大電流，可能是定電流或折返式（foldback）。","g":"arch","lv":3},{"p":"architecture.html","a":"buck","t":"Buck 降壓轉換器","s":"D = VOUT/VIN（理想） ΔIL = VOUT(1 − D) / (L·fSW) ΔVOUT ≈ ΔIL / (8·fSW·COUT) + ΔIL·ESR 同步 vs 非同步：低側用 MOSFET（同步）取代蕭特基二極體，省掉 0.3–0.5 V 的二極體壓降，低輸出電壓時效率差很多。代價是需要死區時間避免上下管同時導通（shoot-through）。 CCM / DCM：電感電流始終大於零是連續導通（CCM）；輕載時電流降到零是不連續（DCM）。同步 Buck 輕載","g":"arch","lv":1},{"p":"architecture.html","a":"boost-bb","t":"Boost、Buck-Boost 與反相","s":"拓撲理想轉換比特性典型用途 BoostVOUT/VIN = 1/(1−D)輸出電流不連續，輸出電容漣波大；有右半平面零點（RHPZ），頻寬受限；關斷時輸入經電感與二極體直通輸出，需 true shutdown單節電池升 5 V、LED 背光、閃光燈 四開關 Buck-Boost可升可降VIN ≈ VOUT 時在 buck / boost 間切換，過渡區要處理好電池 3.0–4.4 V 輸出 3.3 V、USB PD 反相 Buck-BoostVOUT = −D/(1−D)·V","g":"arch","lv":1},{"p":"architecture.html","a":"charge-pump","t":"電荷泵（切換電容）","s":"電荷泵只用開關與電容轉換電壓，沒有電感。轉換比固定（×2、×1.5、÷2、−1），在比例「剛好」時效率很高；比例不對時，多出的電壓仍然會像 LDO 一樣變成損耗。 2:1 分壓電荷泵：手機快充把 USB 輸入的 2 倍電池電壓直接對半轉換，效率可達 97–98%，比 Buck 充電器省很多熱。 倍壓與負壓：給 NMOS 傳輸元件或高側開關的閘極驅動、LCD 偏壓、RS-232 介面。 混合式（hybrid）：電荷泵加電感（例如 3-level buck、Dickson + 電","g":"arch","lv":1},{"p":"architecture.html","a":"pmic","t":"PMIC：把整套電源放進一顆晶片","s":"PMIC 把多路 Buck、LDO、Boost、負載開關、上電時序控制、監控 ADC、看門狗、RTC、充電器、數位介面整合在一起。好處是面積小、時序和監控由同一顆晶片負責；挑戰是多個切換電源與敏感的類比電路共用基板，熱與雜訊耦合、測試複雜度都大幅增加。 領域典型配置重點 手機 / 平板6–12 路 Buck、20–30 路 LDO、充電器、電量計、RTC極低 IQ、DVS 動態調壓、SPMI / I²C、多 PMIC 協同 應用處理器 / FPGA4–8 路 Buck、數路 ","g":"arch","lv":1},{"p":"architecture.html","a":"glossary","t":"名詞解釋","s":"","g":"arch","lv":1},{"p":"architecture.html","a":"glossary","t":"LDO","s":"Low Dropout regulator，低壓差線性穩壓器。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"PMIC","s":"Power Management IC，整合多路電源與管理功能的晶片。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"VDO","s":"Dropout voltage，維持穩壓所需的最小輸入輸出壓差。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"IQ","s":"Quiescent current，靜態電流。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"Duty cycle D","s":"高側開關導通時間佔切換週期的比例。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"CCM / DCM","s":"Continuous / Discontinuous Conduction Mode，電感電流連續或不連續。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"PFM","s":"Pulse Frequency Modulation，輕載時降低切換頻率以提高效率。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"Shoot-through","s":"上下管同時導通，造成 VIN 直接對地短路。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"RHPZ","s":"Right Half-Plane Zero，Boost / Buck-Boost 特有的右半平面零點，限制迴路頻寬。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"DVS","s":"Dynamic Voltage Scaling，動態調壓。","g":"arch","lv":3},{"p":"architecture.html","a":"glossary","t":"Post-regulation","s":"DC-DC 之後再接 LDO，用 LDO 的 PSRR 濾掉切換漣波。","g":"arch","lv":3},{"p":"process.html","a":"bcd","t":"BCD 是什麼","s":"1980 年代中期 ST（當時的 SGS）推出第一代 BCD 製程，把雙極電晶體（類比精度）、CMOS（邏輯）與 DMOS（功率）放在同一片晶圓上。之後各家晶圓廠都發展了自己的 BCD 平台，節點一路從數 µm 微縮到 0.18 µm、0.13 µm、90 nm，近年甚至到 55 / 40 nm，以便在 PMIC 中整合更多數位邏輯與記憶體。 電壓等級典型節點代表應用 5–7 V0.13 µm–55 nm手機 PMIC、SoC 周邊電源、DDR5 PMIC 20–40 V0.","g":"fab","lv":1},{"p":"process.html","a":"device-menu","t":"元件選單","s":"類別元件電源 IC 中的用途 CMOS1.5 / 1.8 V 核心、5 V I/O、HV CMOS數位控制、暫存器、OTP 控制、閘極驅動前級 DMOSN-LDMOS、P-LDMOS（7–80 V）、隔離型 LDMOSBuck 高 / 低側開關、LDO 傳輸元件、負載開關 Bipolar垂直 NPN、橫向 / 基板 PNP帶隙參考、溫度感測、低雜訊輸入級 二極體齊納、蕭特基、ESD 二極體參考、鉗位、ESD 保護、自舉（bootstrap） 電阻N+ / P+ 多晶矽、高阻多","g":"fab","lv":1},{"p":"process.html","a":"ldmos","t":"LDMOS：耐壓與導通電阻的取捨","s":"LDMOS 的關鍵指標是比導通電阻 Rsp = RDS(on) × 面積（mΩ·mm²）。漂移區越長、摻雜越淡，耐壓越高，但電阻也越大；矽的理論極限約為 Rsp ∝ BV2.5。RESURF、多重場板、超接面（super-junction）等技術都在推近這個極限。 面積就是成本：在 5 V PMIC 中，功率開關常佔晶片面積的 30–50%。Rsp 每降低 20%，同樣效率下開關就能縮小 20%。 開關損失：品質因數 FOM = RDS(on) × Qg（或 × Qgd）。高","g":"fab","lv":1},{"p":"process.html","a":"isolation","t":"隔離與寄生","s":"同一片 P 基板上同時有切換到 VIN 的功率節點、數十 µV 精度的類比電路、和 GHz 時脈的邏輯，彼此之間必須隔開。 隔離方式做法優點缺點 接面隔離（JI）N 型埋層（NBL）+ 深 N 井包住元件，與 P 基板形成反偏 PN 接面成本低、成熟寄生 BJT、漏電隨溫度上升、佔面積 深溝槽隔離（DTI）蝕刻深溝槽填氧化物 / 多晶矽，把元件圍起來面積小、側向寄生少製程較貴，溝槽應力 SOI元件做在埋入氧化層上完全介電隔離、無基板注入、高溫漏電小晶圓貴、散熱差、自熱效應","g":"fab","lv":1},{"p":"process.html","a":"substrate-injection","t":"基板注入：切換節點的副作用","s":"Buck 的低側開關在死區時間內，電感電流經由低側的體二極體續流，SW 節點會被拉到地以下約 −0.7 V。此時 N 型汲極對 P 基板正偏，大量少數載子（電子）注入基板，在基板中擴散數百 µm，被附近其他 N 井收集，形成誤動作電流。 症狀：帶隙參考在切換瞬間跳動、比較器誤觸發、類比 ADC 讀值出現與切換頻率同步的誤差，嚴重時觸發 latch-up。 對策：功率元件外圍加 N+ / P+ 雙重保護環（guard ring）收集載子、縮短死區、增大敏感電路與功率級距離、使用","g":"fab","lv":2},{"p":"process.html","a":"passives","t":"電阻與電容","s":"元件片電阻 / 密度溫度係數注意事項 P+ 多晶矽電阻100–300 Ω/□約 +100 ppm/°C 量級（依摻雜，可正可負）回授分壓常用；兩電阻比例才是重點，絕對值誤差 ±20% 也無妨 高阻多晶矽1–3 kΩ/□負，可達 −1000 ppm/°C 以上低 IQ 分壓（MΩ 級）；對氫、應力敏感，封裝後可能漂移 擴散電阻50–2000 Ω/□正，千 ppm/°C 等級有電壓係數與接面漏電，高溫精度差 薄膜電阻（SiCr、TaN）數百 Ω–kΩ/□可接近 0精密參考、可雷射","g":"fab","lv":1},{"p":"process.html","a":"metal","t":"厚金屬、導通電阻與電遷移","s":"一顆 3 A 的 Buck，若高側 RDS(on) 是 40 mΩ，晶片上的金屬走線和封裝打線可能再加 10–30 mΩ。所以電源製程通常有 3–6 µm 的厚頂層金屬，甚至在晶圓上再做一層銅 RDL，直接把電流從功率元件上方引到凸塊或焊墊。 電遷移（EM）：電流密度過高時金屬原子被電子推移，形成空洞或凸起。設計時每段金屬與每個 via 都要依溫度檢查電流密度上限，高溫（125–150 °C）下的允許值低得多。 Bond-over-active：焊墊直接放在主動元件上方可省面","g":"fab","lv":1},{"p":"process.html","a":"trim-fuse","t":"修調：熔絲、OTP 與 MTP","s":"製程變異讓帶隙電壓的初始誤差可能達 ±1–2%，振盪器頻率 ±10–20%，而產品規格要 ±0.5–1%、±2–3%。辦法是在晶圓測試（CP）或封裝後測試（FT）時量測、計算、再燒錄修調碼。 方式原理時機注意事項 多晶矽 / 金屬熔絲大電流燒斷CP（探針可直接接觸）需開窗或專用墊；燒不斷、殘留電阻、長期「再生長」造成修調值改變 雷射修調雷射切斷金屬或薄膜電阻CP需專用設備、晶片表面開窗；可做連續修調 齊納燒熔（zener zap）反向大電流讓齊納短路CP 或 FT可在封裝後修","g":"fab","lv":1},{"p":"process.html","a":"matching","t":"匹配與應力","s":"LDO 的輸出精度主要來自差動對與電流鏡的偏移、分壓電阻的比例、帶隙中 BJT 的面積比，它們都是「兩個相同元件到底有多相同」的問題。 σ(ΔVT) = AVT / √(W·L) σ(ΔR/R) = AR / √(W·L) Pelgrom 定律：失配與元件面積的平方根成反比。要讓偏移減半，面積要變成 4 倍。 共質心佈局（common centroid）、交錯排列（interdigitation）、虛設元件（dummy）：抵消線性梯度與邊緣效應。 遠離應力源：精密元件不要放在","g":"fab","lv":1},{"p":"process.html","a":"trends","t":"製程趨勢","s":"更細的 BCD 節點：手機與 DDR5 PMIC 要整合大量數位控制、OTP 和 ADC，推動 BCD 走到 55 / 40 nm，同時保留 5 V LDMOS。 GaN 與 SiC：48 V 伺服器電源、車載充電器、快充開始用 GaN HEMT 做開關，切換速度與 FOM 比矽好一個數量級；控制器仍在矽上，形成多晶片或單晶 GaN 整合。 整合被動元件：矽電容（deep trench capacitor）、封裝內電感（PwrSiP、IVR），讓電源更靠近處理器，降低供電網路","g":"fab","lv":1},{"p":"process.html","a":"glossary","t":"名詞解釋","s":"","g":"fab","lv":1},{"p":"process.html","a":"glossary","t":"BCD","s":"Bipolar-CMOS-DMOS 整合製程。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"LDMOS","s":"Laterally Diffused MOS，橫向擴散 MOS，電源 IC 的主力功率元件。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"Rsp","s":"Specific on-resistance，比導通電阻，RDS(on) × 面積。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"RESURF","s":"Reduced Surface Field，利用摻雜與場板讓漂移區電場分佈更均勻，提高耐壓。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"NBL","s":"N-type Buried Layer，N 型埋層，用於接面隔離與降低寄生 PNP 增益。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"DTI","s":"Deep Trench Isolation，深溝槽隔離。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"Guard ring","s":"保護環，包圍元件以收集注入載子、降低 latch-up 風險。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"OTP","s":"One-Time Programmable，只能寫一次的非揮發記憶。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"Piezoresistive effect","s":"壓阻效應，應力改變半導體電阻與載子遷移率。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"SOA","s":"Safe Operating Area，安全操作區，電壓、電流、時間的允許組合。","g":"fab","lv":3},{"p":"process.html","a":"glossary","t":"FOM","s":"Figure of Merit，例如 RDS(on)·Qg，衡量開關元件的綜合表現。","g":"fab","lv":3},{"p":"design.html","a":"ldo-loop","t":"LDO 迴路：極點、零點與相位裕度","s":"把 LDO 看成一個負回授放大器。開迴路增益 AOL = AEA · gm,pass · Rout · β，其中 β = R2/(R1+R2)。決定穩定度的是幾個極點與零點的位置： 極零點位置特性 輸出極點 pout1 / (2π · Rout · COUT)，Rout = ro,pass ∥ Rload隨負載移動：重載時 Rout 變小，極點往高頻移動數十倍 閘極極點 pgate1 / (2π · Ro,EA · Cgate)傳輸元件越大、Cgate 越大，極點越低 ESR","g":"design","lv":1},{"p":"design.html","a":"esr-window","t":"ESR 穩定窗口與陶瓷電容","s":"早期 LDO 是配合鉭電容或鋁電解電容設計的，它們有 0.1–數 Ω 的 ESR，正好提供穩定所需的零點。規格書會畫一張「ESR vs 負載電流」的穩定區域圖，俗稱 tunnel of death：ESR 太低（陶瓷電容）會振盪，ESR 太高也會振盪。 多層陶瓷電容（MLCC）普及後，ESR 只有數 mΩ，舊 LDO 直接換上陶瓷電容就會振盪。現代 LDO 改成內部補償：在 EA 內做米勒補償或加內部零點，讓主極點不再依賴 ESR，標示為「stable with cerami","g":"design","lv":1},{"p":"design.html","a":"capless","t":"無外部電容 LDO 與 NMOS LDO","s":"SoC 內部的數位 LDO 或晶片內 LDO 沒有空間放 µF 電容，只有晶片上的數百 pF 到數 nF。這時輸出極點跑到高頻，主極點改放在 EA 內部（米勒補償），代價是頻寬受限、負載暫態時下衝大。常見改善方式： 翻轉電壓隨耦器（FVF）、局部快速回授迴路：在輸出放一個快速的區域迴路，處理高頻暫態。 電容耦合的暫態加速：偵測輸出 dV/dt，直接推動傳輸元件閘極。 數位 LDO（DLDO）：用一排數位控制的開關取代類比 EA，可在極低電壓工作，但有極限環振盪與量化漣波。 N","g":"design","lv":1},{"p":"design.html","a":"psrr","t":"PSRR：把輸入漣波擋在外面","s":"PSRR = 20·log(ΔVIN/ΔVOUT)。它不是一個數字，而是一條隨頻率變化的曲線，可以大致分成三段： 頻段主導機制怎麼改善 低頻（< 迴路頻寬的 1/10）迴路增益：PSRR ≈ AOL提高 EA 增益、參考電壓本身的 PSRR、參考低通濾波 中頻（接近迴路頻寬）迴路增益隨頻率下降，PSRR 跟著變差，常出現最差點提高頻寬、閘極驅動跟隨 VIN（前饋抵消） 高頻（> 數 MHz）迴路已無增益，靠 COUT 與寄生電容分壓；PMOS 的 Cgs 把輸入直接耦合過來大","g":"design","lv":1},{"p":"design.html","a":"noise","t":"輸出雜訊","s":"LDO 的輸出雜訊大多來自參考電壓與 EA 輸入級，再被回授分壓放大 (1 + R1/R2) 倍。所以同一顆 LDO，3.3 V 輸出的雜訊會比 1.2 V 大。 NR / SS 腳：參考電壓後接外部電容做 RC 低通，把參考雜訊濾掉；同時兼做軟啟動，電容越大啟動越慢。 前饋電容 CFF：跨在 R1 上，讓高頻時回授增益變 1，雜訊不再被放大；同時在迴路中增加一組零極點，可以改善暫態，但也可能改變相位裕度。 1/f 雜訊：低頻雜訊由 MOS 的閃爍雜訊主導，BJT 或大面積 ","g":"design","lv":1},{"p":"design.html","a":"transient","t":"負載暫態","s":"負載電流在 1 µs 內從 1 mA 跳到 500 mA 時，迴路來不及反應，這段時間的電流全部由輸出電容提供： ΔVOUT ≈ ΔI · ESR + ΔI · tresp / COUT tresp ≈ 1/(2π·fUGB) + Cgate·ΔVgate/Islew 迴路頻寬：越高反應越快，但與穩定度互相拉扯。 閘極迴轉率：大傳輸元件的閘極電容可達數百 pF，EA 輸出電流不夠時，閘極要花很久才能轉到新的電壓。常見解法是在 EA 與傳輸元件間加緩衝級，或用動態偏壓（重載或偵","g":"design","lv":1},{"p":"design.html","a":"bandgap","t":"帶隙參考","s":"BJT 的 VBE 約 0.6–0.7 V，溫度係數約 −2 mV/°C（CTAT）；兩顆電流密度不同的 BJT 的 ΔVBE = (kT/q)·ln(N) 與絕對溫度成正比（PTAT）。把兩者按比例相加，就能在某個溫度附近讓溫度係數為零，總和約 1.2 V，接近矽的帶隙電壓。 VREF = VBE + K · (kT/q)·ln(N) ≈ 1.2 V （K 由電阻比決定） 曲率：VBE 本身不是完美線性，一階補償後仍有拋物線形的殘餘誤差，全溫約 10–30 ppm/°C；高","g":"design","lv":1},{"p":"design.html","a":"protection","t":"保護電路","s":"保護做法設計重點 / 常見陷阱 限流（定電流）偵測傳輸元件電流（鏡像 sense FET），超過門檻就限制閘極短路時功耗 = VIN·ILIM，很快就熱關機 折返限流（foldback）VOUT 越低，允許電流越小降低短路功耗；但重載或大電容負載可能啟動不起來（卡在低電壓狀態） 熱關機（TSD）晶片上的溫度感測，常見 150–170 °C 觸發、10–20 °C 遲滯遲滯太小會快速開關造成振盪；感測器要放在最熱的傳輸元件旁 欠壓鎖定（UVLO）VIN 低於門檻時關閉輸出，帶遲","g":"design","lv":1},{"p":"design.html","a":"dcdc-control","t":"DC-DC 控制模式","s":"控制模式原理優點缺點 電壓模式（VM）誤差電壓與固定斜坡比較產生 PWM抗雜訊、輕載穩定LC 雙極點需 Type III 補償，暫態較慢 峰值電流模式（PCM）電感電流峰值與誤差電壓比較內建逐週期限流、補償簡單（Type II）、易多相均流D > 50% 時次諧波振盪，需斜率補償；需電流偵測與遮蔽時間 谷值電流模式偵測電感電流谷值適合低 D（高降壓比）D 小時的次諧波問題 固定導通時間（COT）VOUT 降到門檻時觸發固定 tON暫態極快、輕載效率好、不需補償網路頻率隨負載變","g":"design","lv":1},{"p":"design.html","a":"compensation","t":"補償網路","s":"交越頻率：一般取 fc ≤ fSW/10（電流模式可到 fSW/5），Boost / Buck-Boost 還要低於 RHPZ 頻率的 1/3–1/5。 Type II（一零兩極）：電流模式常用，零點放在功率級主極點附近，高頻極點放在 ESR 零點或 fSW/2。 Type III（兩零三極）：電壓模式用來補償 LC 雙極點造成的 180° 相位急轉。 內部補償：許多整合 Buck 把補償做在晶片內，換取簡單，但限制了可用的 L、C 範圍，客戶用錯電感電容就可能不穩定。 量測","g":"design","lv":1},{"p":"design.html","a":"gate-drive","t":"閘極驅動、死區與自舉","s":"自舉（bootstrap）：N 型高側開關的閘極要比 SW 高 VGS，用一顆電容在低側導通時充電，高側導通時「浮」在 SW 上。100% duty 時自舉電容無法補充，需要定期強制低側導通或內建電荷泵。 死區時間：防止上下管同時導通。太長時體二極體導通時間增加，損失變大且加重基板注入；太短則有 shoot-through 風險。自適應死區偵測對方閘極已關斷才開啟。 切換速度與 EMI：SW 節點 dV/dt 越快，切換損失越小，但振鈴與 EMI 越大。可分段驅動、可調斜率，","g":"design","lv":1},{"p":"design.html","a":"pmic-digital","t":"PMIC 的數位部分","s":"上電 / 斷電時序器：依 OTP 設定的順序與延遲開啟每一路電源，並等待前一路 PG 才開下一路。斷電時序同樣重要，錯誤時可能損壞處理器或造成閂鎖。 介面：I²C、SPI、SPMI（行動裝置）、PMBus（伺服器）、SVID / SVI3（x86 處理器），用來讀寫電壓、模式、故障狀態與遙測值。 DVS：收到新電壓命令後以設定的斜率（例如 10 mV/µs）調整參考電壓，迴路要在整個過程中保持穩定；降壓時若轉換器不吸電流（PFM），電壓會降得比命令慢。 故障處理狀態機：發生 ","g":"design","lv":1},{"p":"design.html","a":"verification","t":"設計驗證","s":"項目內容 PVT 角落製程角（TT / FF / SS / FS / SF）× 電壓 × 溫度（−40 / 25 / 125 / 150 °C） 蒙地卡羅偏移、精度、修調前後的分佈，估計良率與修調範圍是否足夠 穩定度掃描負載 0–Imax × COUT（含 DC bias 衰減）× ESR × ESL × 溫度，所有組合的相位裕度 暫態與啟動軟啟動、短路後恢復、熱關機遲滯、VIN 慢升 / 快升 / 掉電（brown-out）、熱插拔 EM / IR功率路徑電流密度、via ","g":"design","lv":1},{"p":"design.html","a":"glossary","t":"名詞解釋","s":"","g":"design","lv":1},{"p":"design.html","a":"glossary","t":"相位裕度 PM","s":"增益降到 0 dB 時，相位距離 −180° 還有多少度。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"UGB","s":"Unity-Gain Bandwidth，迴路增益為 1 的頻率，即交越頻率。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"ESR / ESL","s":"電容的等效串聯電阻 / 電感。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"Miller 補償","s":"在放大級跨接電容，利用米勒效應把主極點移到低頻並分離極點。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"CFF","s":"Feedforward capacitor，跨在上分壓電阻的前饋電容。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"Foldback","s":"折返限流：輸出電壓下降時限流值跟著降低。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"Hiccup","s":"打嗝模式：故障時關閉一段時間再嘗試重啟。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"Slope compensation","s":"斜率補償，防止峰值電流模式在 D > 50% 時的次諧波振盪。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"COT","s":"Constant On-Time，固定導通時間控制。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"PTAT / CTAT","s":"與絕對溫度成正比 / 成反比的電壓或電流。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"SPMI","s":"System Power Management Interface，MIPI 制定的行動裝置電源管理匯流排。","g":"design","lv":3},{"p":"design.html","a":"glossary","t":"FMEDA","s":"Failure Modes, Effects and Diagnostic Analysis，功能安全分析方法。","g":"design","lv":3},{"p":"production.html","a":"flow","t":"生產流程","s":"","g":"mfg","lv":1},{"p":"production.html","a":"wat","t":"WAT：晶圓出廠前的電性體檢","s":"晶圓允收測試（WAT，又稱 PCM）在切割道上的測試鍵量測基本元件參數：VT、IDSAT、片電阻、接觸電阻、BJT β、LDMOS Rsp 與崩潰電壓、電容值、氧化層崩潰等。 允收：每片量 5–9 點，超出規格的晶圓不出貨或降級處理。 和產品參數的關聯：帶隙的修調前分佈和 BJT VBE、電阻片電阻高度相關；RDS(on) 和 LDMOS 的 Rsp 相關。PE 會建立 WAT 與 CP 參數的相關模型，提早預警。 製程飄移：WAT 落在規格內但偏向一邊（例如片電阻偏高 2σ","g":"mfg","lv":1},{"p":"production.html","a":"cp-trim","t":"CP 測試與修調","s":"晶圓測試（CP，chip probing）用探針卡接觸每顆晶粒的焊墊。電源 IC 的 CP 有兩個特殊任務：修調，以及在探針接觸電阻存在下量測大電流參數。 開短路與漏電確認探針接觸與 ESD 結構正常。 量修調前參數：帶隙電壓、振盪頻率、偏壓電流、限流門檻等。 計算修調碼：依修調前值與目標值，查表或公式算出每一組熔絲 / OTP 位元。 燒錄：熔絲燒斷或寫入 OTP，記錄修調碼。 修調後驗證：重新量測，確認落在窄規格內；燒不斷或修調後仍超規的晶粒判為失效。 其他參數：IQ、U","g":"mfg","lv":1},{"p":"production.html","a":"assembly","t":"封裝","s":"封裝θJA（JEDEC 板，量級）特點典型用途 SOT-23 / SC-70180–250 °C/W便宜、好焊、好目檢小電流 LDO、負載開關 SOIC / MSOP（含 exposed pad）40–120 °C/W引腳外露，車用目檢容易車用 LDO、工業 DFN / QFN（裸露散熱墊）30–60 °C/W散熱墊焊在 PCB 上導熱；引腳側面需可濕潤側翼（wettable flank）才能做 AOIBuck、PMIC、中功率 LDO WLCSP50–100 °C/W最小、","g":"mfg","lv":1},{"p":"production.html","a":"ft","t":"FT 最終測試","s":"封裝後的最終測試（FT）在 handler 上自動上下料，量測規格書上的保證參數。和 CP 相比，FT 可以測大電流、實際切換、熱特性，也能抓到封裝造成的問題。 溫度：消費性產品常只測常溫，用設計與特性化資料保證全溫；車用通常要求冷（−40 °C）/ 常 / 熱（125 °C 以上）三溫測試或至少兩溫。 測試時間：一顆 LDO 約 0.3–1 秒，大型 PMIC 可達 5–20 秒。每秒測試成本約數美分，對單價低的產品影響很大，所以測試項目與穩定等待時間都要精算。 功能測試：","g":"mfg","lv":1},{"p":"production.html","a":"yield","t":"良率","s":"總良率 Y = Yfab × YCP × Yassy × YFT YCP ≈ e−A·D0 × Yparam 缺陷良率：與晶粒面積和缺陷密度有關。電源 IC 晶粒小（1–10 mm²），缺陷良率通常很高。 參數良率：常常才是主要損失來源，例如修調範圍不足、IQ 偏高、UVLO 門檻超規。 良率損失柏拉圖：每週依失效 bin 排序，前三名通常佔 70–80% 損失，是改善的起點。 晶圓圖：邊緣低良率、環狀、刮痕、特定曝光區塊（reticle）的模式，可以直接指向製程或探針卡問題","g":"mfg","lv":1},{"p":"production.html","a":"cpk","t":"Cpk 與 SPC","s":"Cp = (USL − LSL) / 6σ Cpk = min(USL − μ, μ − LSL) / 3σ Cpk超規比例（常態分佈、單邊）一般解讀 1.00≈ 1350 ppm不足 1.33≈ 32 ppm消費性常見最低要求 1.67≈ 0.3 ppm車用常見要求（關鍵參數） 2.00≈ 0.001 ppm六標準差等級 測試極限與規格極限：測試極限（test limit）通常比規格書極限更緊，中間的差是 guard band，用來涵蓋測試機誤差、溫度差、長期漂移。 SPC","g":"mfg","lv":1},{"p":"production.html","a":"pat","t":"PAT 與零缺陷","s":"車用客戶的目標是 < 1 DPPM（每百萬顆不到一顆不良），甚至零缺陷。只看規格界限不夠，因為一顆「通過規格但明顯偏離同批」的晶片，往往帶有潛在缺陷。 部件平均測試（PAT）：依 AEC-Q001，以同批或同晶圓的分佈計算動態界限（例如 μ ± 6σ 的穩健估計），落在外面的離群值即使在規格內也剔除。 地理位置篩選：GDBN（good die in bad neighborhood）把被大量失效晶粒包圍的良品也剔除；也會剔除整片晶圓的特定區域或整片低良率晶圓。 IDDQ 與漏","g":"mfg","lv":1},{"p":"production.html","a":"traceability","t":"追溯","s":"客訴發生時第一個問題是「這顆是哪一批、哪一片、哪個位置做的」。追溯鏈通常是： 封裝打印：料號 + 日期碼 + 批號代碼（小封裝空間有限，可能只有 3–4 個字元）。 晶片內 ECID：在 CP 時把 lot / wafer / X-Y 寫入 OTP，事後可透過介面讀出。PMIC 與車用產品常見。 資料庫串接：WAT、CP、FT、修調碼、測試機與探針卡編號、封裝批次、材料批號全部以批號串起來，才能做客訴時的「同批風險評估」。 保存期限：車用通常要求生產資料保存 15 年以上。","g":"mfg","lv":1},{"p":"production.html","a":"pcn","t":"PCN 與變更管理","s":"任何可能影響形狀、適配、功能、品質或可靠度的變更，都要提前通知客戶（依 JESD46，通常至少 90 天），重大變更要附上驗證資料，讓客戶評估或重新認證。 變更類型例子通常需要 晶圓廠 / 製程換廠、換節點、光罩改版、製程步驟調整完整或部分 AEC-Q100 重新驗證、特性化比較 設計電路修正、修調演算法變更特性化與驗證 封裝換封裝廠、金線改銅線、導線架電鍍、塑封料封裝相關可靠度（溫度循環、THB / HAST、MSL） 測試換測試機、測試程式或測試極限調整相關性報告；車用通","g":"mfg","lv":1},{"p":"production.html","a":"capacity","t":"產能、交期與雙來源","s":"8 吋晶圓廠：大量電源 IC 仍在 8 吋 BCD 產線上生產。2020–2022 年的缺貨潮中，8 吋產能是最緊的瓶頸之一，交期拉長到 40–52 週以上。 雙來源（second source）：大客戶要求同一料號在兩個晶圓廠或兩個封裝廠都有產能。每個來源都要完成驗證，並證明特性一致。 腳位相容替代：短缺時客戶常改用其他廠商的腳位相容料，但補償方式、軟啟動、PG 時序、穩定電容範圍不同，換料後的振盪、啟動問題是常見的應用支援工作。","g":"mfg","lv":1},{"p":"production.html","a":"glossary","t":"名詞解釋","s":"","g":"mfg","lv":1},{"p":"production.html","a":"glossary","t":"WAT / PCM","s":"Wafer Acceptance Test / Process Control Monitor，晶圓允收測試。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"CP","s":"Chip Probing，晶圓針測。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"FT","s":"Final Test，封裝後的最終測試。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"Bin","s":"測試結果分類，例如 Bin 1 良品、其他 bin 代表各種失效。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"Guard band","s":"測試極限比規格界限內縮的裕度。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"OCAP","s":"Out-of-Control Action Plan，製程失控時的處理計畫。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"PAT","s":"Part Average Testing，以同批分佈剔除離群值。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"DPPM","s":"Defective Parts Per Million，每百萬顆不良數。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"MSL","s":"Moisture Sensitivity Level，濕敏等級。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"ECID","s":"Electronic Chip ID，寫在晶片內的唯一識別碼。","g":"mfg","lv":3},{"p":"production.html","a":"glossary","t":"PCN / EOL / LTB","s":"產品變更通知 / 停產 / 最後購買。","g":"mfg","lv":3},{"p":"test.html","a":"ldo-params","t":"LDO 參數怎麼量","s":"參數量測方法陷阱 輸出電壓精度固定 VIN、負載，量 VOUT要用 Kelvin 量在接腳，否則量到走線壓降 線性調節率VIN 從最小掃到最大，ΔVOUT/ΔVINVIN 最小值要離開壓差區 負載調節率負載從最小到最大，ΔVOUT/ΔIOUT大電流時自熱會改變 VOUT；用脈衝量測區分電氣與熱效應 壓差 VDO降低 VIN 直到 VOUT 掉到標稱值的某比例（如 −2% 或 −100 mV），記錄 VIN − VOUT；或設 VIN = VOUT(nom) × 某比例直接量定","g":"test","lv":1},{"p":"test.html","a":"dcdc-params","t":"DC-DC 參數","s":"效率：η = POUT/PIN，四線量測電壓、精密分流量電流，每個負載點等熱平衡。1% 的量測誤差就足以讓效率曲線「看起來」不同。 RDS(on)：用測試模式把高側或低側固定導通，灌入已知電流，以 Kelvin 量測跨壓。 切換頻率與最小導通時間：量 SW 波形；量產可用內部振盪器的分頻輸出，避免接大電感。 峰值 / 谷值限流：逐週期限流門檻，需要實際電感或測試模式。 輕載模式切換點、漣波、負載暫態：多數屬於特性化項目，量產只做功能確認。","g":"test","lv":1},{"p":"test.html","a":"ate","t":"ATE 量產測試","s":"電源 IC 的 ATE（例如混合訊號測試機）有多組 DPS（裝置電源）、PMU（精密量測單元）、高電流 / 高電壓源、數位通道與數位化器（digitizer）。量產測試的核心問題是在 0.5 秒內量完所有保證參數，又不能犧牲精度。 穩定時間：LDO 輸出接大電容時，每改一次條件都要等數 ms 到數十 ms。量產測試通常在 load board 上用較小的電容，或用繼電器切換。 測試模式：透過特殊腳位序列或 I²C 命令進入測試模式，把內部節點（參考電壓、偏壓電流、振盪器）接到","g":"test","lv":1},{"p":"test.html","a":"dft","t":"可測試性設計（DFT）","s":"類比測試匯流排：把關鍵內部節點透過多工器引到一支測試腳或功能腳。 修調暫存器的「試修」：先把修調碼寫入暫存器（不燒錄）量測結果，確定正確後才燒 OTP，降低燒錄錯誤。 保護電路旁路：測試模式下暫時關閉 UVLO、軟啟動或熱關機延遲。 數位掃描鏈：PMIC 的時序器與暫存器以 scan 測試，涵蓋率目標 > 95%。 測試模式的安全性：要防止在客戶系統中被雜訊或錯誤的 I²C 命令誤觸。曾有產品因為上電時腳位雜訊誤入測試模式，造成現場輸出異常。","g":"test","lv":1},{"p":"test.html","a":"kelvin","t":"Kelvin 量測與大電流","s":"測一顆 RDS(on) 30 mΩ 的開關時，socket 的接觸電阻可能就有 20–50 mΩ，而且會隨使用次數增加。解法是 Kelvin（四線）量測：一對 force 線送電流，另一對 sense 線在接腳上量電壓，sense 線幾乎沒有電流，接觸電阻不影響讀值。 Socket 磨耗：接觸電阻慢慢上升，RDS(on) 或負載調節率的分佈往一邊移動，最後造成良率下降或測試機之間不一致。要以 golden unit 每班檢查並設定更換次數。 脈衝測試：大電流測試用 0.1–1","g":"test","lv":1},{"p":"test.html","a":"correlation","t":"相關性與 GR&R","s":"同一顆晶片在 CP、FT、實驗室、客戶產線上量到的值不會完全相同。相關性（correlation）就是要證明差異是已知且可接受的。 Golden unit：一組已在實驗室精確量測的樣品，用來校驗每台測試機、每個 load board。 GR&R（量測系統分析）：重複性（同一台重測）與再現性（不同台 / 不同人）佔公差的比例，< 10% 為佳，10–30% 視情況可接受，> 30% 不可接受。 Tester-to-tester：不同測試機的偏移要小於 guard band 的一","g":"test","lv":1},{"p":"test.html","a":"bench","t":"實驗室特性化","s":"項目方法與設備 全溫參數熱流罩（thermostream）或溫箱，−40 至 150 °C，每點等待熱平衡 迴路 Bode 圖網路分析儀 + 注入變壓器 / 注入電阻，在回授路徑注入訊號；掃不同負載與電容 負載暫態快速電子負載或 MOSFET 切換電阻，上升時間 < 1 µs；探棒用短接地彈簧 PSRR線路注入器或功率放大器在 VIN 疊加正弦波，網路分析儀量比值 雜訊電池供電、屏蔽盒、低雜訊前置放大、頻譜分析儀 效率與熱四線量測、功率分析儀、熱像儀、熱電偶 EMI預掃描的近","g":"test","lv":1},{"p":"test.html","a":"qual","t":"可靠度驗證：AEC-Q100","s":"車用 IC 的標準是 AEC-Q100，消費性與工業產品常以 JEDEC JESD47 為基礎。典型要求是 3 個批次 × 77 顆，零失效，前後量測參數並比較漂移。 測試條件（典型）針對的失效機制 HTOL 高溫工作壽命TJ 125–150 °C，最大工作電壓，1000 h氧化層、熱載子、電遷移、參數漂移 ELFR 早期失效率短時間高溫偏壓，大樣本製程缺陷造成的早夭 TC 溫度循環−55/−65 ↔ 150 °C，500–1000 循環打線、黏晶、焊點、介面分層 THB /","g":"test","lv":1},{"p":"test.html","a":"esd-lu","t":"ESD 與 latch-up","s":"模型模擬什麼典型等級 HBM（人體放電）帶電人體接觸接腳，100 pF / 1.5 kΩ±2 kV（一般）、±4 kV（車用常見） CDM（帶電元件）晶片本身帶電後一支腳接觸接地，ns 級大電流±500 V，角落腳 ±750 V 系統級 IEC 61000-4-2成品被人碰觸，能量遠大於 HBM±8 kV 接觸 / ±15 kV 空氣（成品層級） HBM 合格 ≠ 系統級合格：IC 的 ±2 kV HBM 不代表接在 USB 或電池端子能承受 ±8 kV。系統需要外部 TVS","g":"test","lv":1},{"p":"test.html","a":"safety","t":"功能安全測試","s":"上電自我測試：監控比較器、參考電壓、看門狗在每次上電時自我檢查，失敗就不放行。 故障注入：設計時在監控路徑上留下可注入故障的開關，量產與現場都能驗證監控電路本身沒壞（潛在故障）。 ATE 涵蓋率：功能安全要求量產測試涵蓋安全機制本身，否則安全機制的硬體缺陷不會被發現。","g":"test","lv":1},{"p":"test.html","a":"glossary","t":"名詞解釋","s":"","g":"test","lv":1},{"p":"test.html","a":"glossary","t":"ATE","s":"Automatic Test Equipment，自動測試設備。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"DPS / PMU","s":"Device Power Supply / Precision Measurement Unit，測試機的電源與精密量測單元。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"Load board","s":"測試機與待測物之間的介面板。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"Kelvin","s":"四線量測，force 與 sense 分開。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"Golden unit","s":"用於校驗量測系統的參考樣品。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"GR&R","s":"Gage Repeatability & Reproducibility，量測系統的重複性與再現性。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"HTOL","s":"High Temperature Operating Life，高溫工作壽命測試。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"HAST","s":"Highly Accelerated Stress Test，高加速溫濕度應力測試。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"HBM / CDM","s":"Human Body Model / Charged Device Model，兩種 ESD 模型。","g":"test","lv":3},{"p":"test.html","a":"glossary","t":"Skew lot","s":"刻意把製程參數做到角落的驗證批。","g":"test","lv":3},{"p":"application.html","a":"power-tree","t":"電源樹","s":"效率預算：電池功率 = Σ(各負載功率 / 該路效率)。LDO 接在 1.9 V 前級後輸出 1.8 V，效率 ≈ 95% × Buck 效率；若直接接 4 V 電池，只剩 45%。 壓差裕度：前級電壓要大於 VOUT + VDO(最大電流、最高溫) + 前級漣波 + PSRR 所需裕度。 電流裕度：峰值電流常是平均的數倍（CPU 突發、RF 發射），要以峰值選擇限流與電感飽和電流。","g":"app","lv":1},{"p":"application.html","a":"sequencing","t":"上電與斷電時序","s":"多數 SoC、FPGA 與 DDR 對各電源軌的上電順序、斜率、間隔有規定。違反時輕則啟動失敗，重則 I/O 透過 ESD 二極體互相灌電流、引起 latch-up。 常見規則：核心先於 I/O、I/O 先於類比；或「任何時刻 VIO 不得高於 VCORE + 某值」。 實作方式：PMIC 內建時序器、用上一路 PG 接下一路 EN、RC 延遲（溫度與容差大，不建議）。 斷電時序：常被忽略。大電容的軌放電慢，小電容的軌先掉，順序可能顛倒，需要主動放電或時序器控制。 預偏壓啟動","g":"app","lv":1},{"p":"application.html","a":"ldo-or-dcdc","t":"選 LDO 還是 DC-DC","s":"條件傾向理由 VIN − VOUT 小（< 0.5 V）且電流中等LDO效率接近 DC-DC，元件少、無雜訊 壓差大、電流 > 200–300 mADC-DCLDO 熱無法處理 RF、PLL、ADC 參考LDO（或 DC-DC + LDO）需要低雜訊與高 PSRR 極輕載長時間待機低 IQ LDO 或負載開關DC-DC 輕載效率與 IQ 仍可能比 nA 級 LDO 差 空間極小、不能有電感LDO 或電荷泵電感佔面積與高度 輸出需高於輸入Boost / Buck-Boost /","g":"app","lv":1},{"p":"application.html","a":"capacitors","t":"電容選擇：MLCC 的 DC bias","s":"這是電源應用最常見的陷阱。高介電常數的 MLCC（X5R、X7R）在加上直流偏壓後，容值會大幅下降；封裝越小、額定電壓越接近工作電壓，掉得越多。 條件（量級）有效容值 / 標稱值 10 µF · 0603 · 6.3 V 額定 · 偏壓 3.3 V約 30–45% 10 µF · 0805 · 10 V 額定 · 偏壓 3.3 V約 55–70% 1 µF · 0402 · 6.3 V 額定 · 偏壓 1.8 V約 60–75% C0G / NP0 任意偏壓≈ 100%（但容","g":"app","lv":1},{"p":"application.html","a":"inductor","t":"電感選擇","s":"電感值：通常讓漣波電流 ΔIL 為最大負載的 20–40%。太小漣波大、損失大；太大暫態慢、體積大。電流模式控制還要考慮斜率補償與電感值的配合。 飽和電流 Isat：要大於限流門檻（不是只大於最大負載），否則短路時電感飽和、電流急升，可能燒毀開關。 溫升電流 Irms 與 DCR：決定銅損。 屏蔽：非屏蔽電感的漏磁會耦合到附近走線與天線。 交流損耗：MHz 等級切換時，鐵芯損失與集膚效應可能比 DCR 損失更大，要用廠商提供的損耗計算工具。 ▶ 在實驗室試試：Buck 電感漣","g":"app","lv":1},{"p":"application.html","a":"thermal","t":"熱設計","s":"TJ = TA + PD · θJA TJ ≈ Ttop + PD · ΨJT θJA 依板子而定：JEDEC 2s2p 測試板（4 層）與客戶的 2 層小板可差 1.5–2 倍。 散熱墊與過孔：QFN / DFN 的裸露墊要有足夠焊錫與熱過孔（例如 0.3 mm 孔、1.0–1.2 mm 間距）連到內層地平面。過孔要塞孔或做阻焊，避免焊錫流失造成空洞。 用 ΨJT 估計接面溫度：在板上量晶片表面溫度（熱電偶或熱像儀），加上 PD·ΨJT。用 θJC 去算會嚴重低估。 鄰近熱","g":"app","lv":1},{"p":"application.html","a":"layout","t":"PCB 佈局","s":"","g":"app","lv":1},{"p":"application.html","a":"layout-buck","t":"Buck 佈局","s":"熱迴路（hot loop）最小化：輸入電容 → 高側 → 低側 → 回到輸入電容的迴路電流是脈衝，迴路面積決定寄生電感、SW 振鈴與 EMI。輸入電容一定要最靠近 VIN 與 PGND 腳，小容值高頻電容放最近。 SW 節點小而短：它是電壓劇烈跳動的天線，只要夠走電流即可，不要大面積鋪銅，下方不要走敏感訊號。 FB 走線：從輸出電容處（或負載處）拉出，遠離 SW 與電感；分壓電阻靠近 FB 腳放。 接地：功率地（PGND）與類比地（AGND）在 IC 下方或輸出電容地單點相接","g":"app","lv":2},{"p":"application.html","a":"layout-ldo","t":"LDO 佈局","s":"輸入與輸出電容緊貼接腳，地端以短而寬的路徑回到 GND 腳。 遠端感測（sense）腳拉到負載處，補償長走線壓降。 NR / SS 電容與 FB 分壓的地回到 LDO 的 GND，而不是遠處的功率地。 散熱墊與銅箔面積依功耗設計。","g":"app","lv":2},{"p":"application.html","a":"emi","t":"EMI 與 EMC","s":"切換頻率選擇：車用避開 AM 頻段（530–1700 kHz），常用 400 kHz（低於 AM）或 2.1 MHz（高於 AM）。 展頻（spread spectrum）：把切換頻率在 ±5–10% 內抖動，降低峰值頻譜，但可能讓下游 ADC 看到寬頻雜訊。 輸入濾波：π 型 LC 濾波器降低傳導 EMI，但要注意濾波器輸出阻抗與轉換器負輸入阻抗的交互作用（Middlebrook 準則），否則會振盪。 邊緣速率控制：降低 SW 的 dV/dt（BOOT 串電阻、可調驅動強度","g":"app","lv":1},{"p":"application.html","a":"hot-plug","t":"熱插拔與輸入保護","s":"插上電源線或電池瞬間，輸入線的電感與低 ESR 陶瓷電容形成 LC 諧振，輸入電壓可能衝到電源電壓的接近兩倍。12 V 適配器插上時可看到 20 V 以上的尖峰，超過 IC 的絕對最大額定就會造成 EOS 損壞。 對策：輸入加阻尼（電解電容或 RC 阻尼）、TVS 二極體、選擇耐壓更高的 IC、負載開關控制湧入電流。 反接：電池或電源線接反時，ESD 二極體與體二極體會導通大電流，需要串聯二極體、P-MOSFET 或理想二極體控制器。 反灌：多電源系統中某一路先上電，透過 I","g":"app","lv":1},{"p":"application.html","a":"automotive","t":"車用電源","s":"情境電壓（12 V 系統，量級）對電源 IC 的要求 冷啟動（cold crank）掉到 3–6 V，持續數十 msBuck 要能 100% duty / 低壓差工作，或用 Buck-Boost 前級 啟停（start-stop）反覆掉到 6–8 V同上，且不能重置 拋負載（load dump）未抑制可達 80–100 V 以上，中央抑制後約 35–40 V40 V 以上耐壓或外部保護 反接−14 V反接保護 跨接啟動（jump start）24–27 V 持續數分鐘持續耐壓","g":"app","lv":1},{"p":"application.html","a":"segments","t":"各領域的重點","s":"領域重點 手機 / 穿戴效率（電池壽命）、IQ、面積與高度、DVS 速度、RF 干擾、音訊嘯叫 AI / 資料中心處理器核心電流數百到上千安培、多相 VR、48 V 匯流排、暫態 di/dt、遙測精度、效率每 0.5% 都是電費 車用寬輸入電壓、EMI、功能安全、Grade 1 / 0 溫度、零缺陷、長期供貨 工業24 V 匯流排與突波、長壽命、寬溫、隔離 IoT / 感測器nA 級 IQ、能量採集、間歇工作 精密類比 / 量測雜訊、PSRR、溫漂、長期漂移 ▶ 資料中心與 ","g":"app","lv":1},{"p":"application.html","a":"selection","t":"選型與設計檢查表","s":"電壓與電流：VIN 範圍（含瞬態）、VOUT、最大與峰值電流、壓差裕度。 熱：最壞條件下 PD，用實際板子估算 TJ。 電容：以 DC bias、溫度、公差、老化後的最小有效容值，確認落在穩定範圍。 雜訊與 PSRR：在負載關心的頻段，而不是只看 1 kHz。 時序與保護：EN、PG、軟啟動、預偏壓、限流方式（foldback 會不會啟動不了）、UVLO 遲滯。 佈局：熱迴路、SW、FB、地、散熱過孔。 EMI 與瞬態：頻率、展頻、輸入濾波、TVS。 驗證：負載暫態、啟動 /","g":"app","lv":1},{"p":"application.html","a":"glossary","t":"名詞解釋","s":"","g":"app","lv":1},{"p":"application.html","a":"glossary","t":"Power tree","s":"電源樹，系統中所有電源軌的轉換關係。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"DC bias","s":"MLCC 容值隨直流偏壓下降的特性。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"ΨJT","s":"接面到封裝頂部的熱特性參數，用於由表面溫度推算接面溫度。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"Hot loop","s":"Buck 中電流脈衝流經的高頻迴路。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"Pre-bias","s":"輸出已有電壓時的啟動情況。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"Spread spectrum","s":"展頻，抖動切換頻率以降低 EMI 峰值。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"Load dump","s":"拋負載，車用發電機在負載突然斷開時產生的高壓瞬態。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"Cold crank","s":"冷啟動，引擎啟動時電瓶電壓大幅下降。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"EOS","s":"Electrical Overstress，電性過應力，超過絕對最大額定造成的損壞。","g":"app","lv":3},{"p":"application.html","a":"glossary","t":"TVS","s":"Transient Voltage Suppressor，瞬態電壓抑制二極體。","g":"app","lv":3},{"p":"sic.html","a":"why-wbg","t":"為什麼是寬能隙","s":"半導體的能隙越寬，能承受的臨界電場越高。同樣的耐壓，漂移區可以做得更薄、摻雜更濃，所以導通電阻大幅下降；元件更小，寄生電容與電荷也更小，可以切換得更快。 特性（量級）Si4H-SiCGaN對電源的意義 能隙1.1 eV3.3 eV3.4 eV高溫漏電小、可在更高溫工作 臨界電場≈ 0.3 MV/cm≈ 2.5–3 MV/cm≈ 3 MV/cm同耐壓下漂移區薄約 10 倍，Rsp 大幅下降 熱導率≈ 1.5 W/cm·K≈ 3–4.9 W/cm·K≈ 1.3 W/cm·K（磊晶","g":"sic","lv":1},{"p":"sic.html","a":"sic-vs-gan","t":"SiC、GaN、Si 怎麼分工","s":"Si 超接面 MOSFETSiC MOSFETGaN HEMT 反向恢復體二極體 Qrr 大，不適合連續導通模式的硬切換圖騰柱體二極體 Qrr 小，可做硬切換圖騰柱 PFC沒有體二極體，Qrr ≈ 0，但反向導通壓降高 切換頻率數十–百 kHz數十–數百 kHz數百 kHz–MHz 耐壓 / 堅固度有雪崩能力有雪崩能力、短路耐受數 µs、熱導好通常沒有雪崩能力，靠設計裕度 閘極驅動0 / +10–12 V常見 +15–20 V 開、0 至 −5 V 關（依料號）閘極耐壓低（約","g":"sic","lv":1},{"p":"sic.html","a":"dc-chain","t":"資料中心的電源鏈","s":"從電網到 GPU 大約經過五到七級轉換。總效率是各級效率相乘： ηtotal = ηUPS × ηPSU × ηIBC × ηVRM 例：0.97 × 0.975 × 0.975 × 0.90 ≈ 0.83 VRM 那一級（0.8 V、上千安培）通常是效率最低的一級，屬於架構章多相 Buck 的範疇；SiC 的貢獻主要在前面的高壓 AC/DC 與 UPS。一個 100 MW 的資料中心，PSU 效率每提高 1 個百分點，就少約 1 MW 的熱，也少了對應的冷卻電力。","g":"sic","lv":1},{"p":"sic.html","a":"psu","t":"機櫃 PSU：SiC 用在哪一級","s":"伺服器 PSU 通常分兩級：前級功率因數校正（PFC）把 AC 整流並升到約 400 V 直流，後級隔離 DC/DC（常見 LLC 諧振轉換器）降到 50 V 左右的匯流排電壓。 無橋圖騰柱 PFC（totem-pole PFC）：省掉整流橋的二極體壓降，效率最高，但高頻臂在連續導通模式下要硬切換，體二極體的反向恢復會造成巨大損失。Si 超接面 MOSFET 的 Qrr 太大做不到，SiC 與 GaN 的出現才讓圖騰柱 PFC 量產化。 多階（multi-level）PFC：","g":"sic","lv":1},{"p":"sic.html","a":"infineon","t":"以 Infineon 為例：產品與參考設計","s":"項目公開資訊重點 CoolSiC MOSFET 400 V（G2）2024 年 5 月發表，針對 AI 伺服器 PSU 的 AC/DC 級；RDS(on) 11–45 mΩ 五個等級、共十款，TOLL 與 D²PAK-7（Kelvin source、.XT 封裝互連）。Infineon 表示用於多階 PFC 可達 99.5% 效率、超過 100 W/in³。 CoolSiC 650 V / 750 V 等傳統 2 階 PFC、UPS、電信電源常用的電壓等級；Infineon ","g":"sic","lv":1},{"p":"sic.html","a":"hvdc","t":"800 V HVDC 與固態變壓器","s":"為什麼要高壓直流：機櫃 100 kW 以上時，54 V 匯流排的電流達數千安培，銅排的重量、壓降和佔用空間都成為瓶頸。電壓提高到 800 V，同功率的電流降到約 1/15。 架構變化：AC→DC 轉換從每台伺服器的 PSU 集中到電力機櫃或側掛模組；伺服器內部要有 800 V → 低壓的高效轉換，這一級是 SiC 與 GaN 的新戰場。 固態變壓器（SST）：用高頻 SiC 轉換器取代 50/60 Hz 的大型變壓器，直接從中壓電網轉到 800 V 直流。目前仍在發展中，Si","g":"sic","lv":1},{"p":"sic.html","a":"design","t":"SiC 設計重點","s":"主題重點 閘極驅動電壓SiC 的跨導較低，需要較高的開啟電壓（常見 +15 至 +20 V，依料號）才能把 RDS(on) 壓到規格值；關斷用 0 V 或負壓（−2 至 −5 V），以防誤導通。照資料手冊的建議值，不要沿用 Si 的 12 V。 米勒誤導通半橋中另一顆開關切換時的高 dV/dt 經 Cgd 把閘極拉高；對策是負壓關斷、米勒鉗位、低阻抗關斷路徑。 Kelvin source功率迴路和閘極迴路共用源極接腳時，di/dt 在源極電感上的壓降會抵消閘極電壓、減慢切換；","g":"sic","lv":1},{"p":"sic.html","a":"manufacturing","t":"製造：SiC 為什麼貴","s":"基板：SiC 晶錠用昇華法（PVT）在 2000 °C 以上長晶，速度慢、良率低，晶圓成本遠高於 Si。主流從 150 mm 轉往 200 mm，以降低每顆晶粒成本。 晶體缺陷：微管、基面差排（BPD）、堆疊錯誤會造成元件失效或長期退化；磊晶層要把 BPD 轉換成無害的穿透刃差排。 高溫製程：離子佈植後需 1600 °C 以上活化退火；閘極氧化層的 SiC/SiO2 介面缺陷密度比 Si 高，影響通道遷移率與 VT 穩定度。 平面閘 vs 溝槽閘：溝槽閘（trench）的通道","g":"sic","lv":1},{"p":"sic.html","a":"test-rel","t":"測試與可靠度","s":"項目SiC 特有的注意點 VT 漂移（BTI）閘極偏壓下介面陷阱充放電讓 VT 漂移；除了靜態 HTGB，業界也做動態閘極應力（交流切換條件）測試，量測時的前處理與時序會影響讀值。 閘極氧化層壽命SiC 的介面與缺陷使外質性早期失效風險較高；常用加嚴的閘極電壓篩選（gate screening）與 TDDB 外推壽命。 雙極退化體二極體長時間導通時，BPD 在電子電洞復合能量下擴展成堆疊錯誤，造成 VF 與 RDS(on) 上升；以磊晶緩衝層與體二極體應力測試篩除。 宇宙射線","g":"sic","lv":1},{"p":"sic.html","a":"issues","t":"常見問題與客訴情境","s":"現象可能原因怎麼查 / 對策 PFC 效率比參考設計低 0.3–0.5%閘極驅動電壓不足（沿用 Si 的 12 V）、沒有 Kelvin source、死區太長讓體二極體導通依資料手冊設定 VGS、量 VGS 實際波形、縮短死區 半橋偶發直通、開關燒毀米勒誤導通、閘極振鈴超過 VGS(max)負壓關斷或米勒鉗位、閘極電阻與佈局、用差動探棒量閘極 長期運轉後 RDS(on) / VF 上升雙極退化、VT 漂移比對出貨前後參數、確認體二極體導通時間與閘極偏壓條件 高壓機台隨機燒毀","g":"sic","lv":1},{"p":"sic.html","a":"sources","t":"資料來源","s":"EE Power：Infineon 12 kW PSU 參考設計 Electronic Design：12 kW 高密度 PSU 參考設計 EE Power：CoolSiC MOSFET 400 V 用於 AI 伺服器 Compound Semiconductor：Infineon 400 V CoolSiC Infineon 白皮書：SiC 在資料中心 PSU 的應用 Business Wire：Infineon 與 NVIDIA 的 800 V 供電架構 Power El","g":"sic","lv":1},{"p":"sic.html","a":"glossary","t":"名詞解釋","s":"","g":"sic","lv":1},{"p":"sic.html","a":"glossary","t":"寬能隙（WBG）","s":"Wide bandgap，能隙明顯大於矽的半導體，例如 SiC、GaN。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"Totem-pole PFC","s":"無橋圖騰柱功率因數校正，省去整流橋的高效率 PFC 拓撲。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"LLC","s":"電感-電感-電容諧振轉換器，常用於隔離 DC/DC，可軟切換。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"Hold-up time","s":"輸入斷電後輸出仍維持在規格內的時間。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"HVDC","s":"High-voltage direct current，高壓直流配電。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"SST","s":"Solid-state transformer，固態變壓器。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"IBC","s":"Intermediate bus converter，中間匯流排轉換器（例如 48 V → 12 V）。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"BPD","s":"Basal plane dislocation，基面差排，SiC 雙極退化的源頭。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"SEB","s":"Single-event burnout，粒子撞擊引發的單粒子燒毀。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"CMTI","s":"Common-mode transient immunity，隔離驅動器對共模 dV/dt 的抗擾能力。","g":"sic","lv":3},{"p":"sic.html","a":"glossary","t":"DPT","s":"Double-pulse test，雙脈衝測試，量測切換特性的標準方法。","g":"sic","lv":3},{"p":"issues.html","a":"symptoms","t":"症狀索引","s":"症狀最常見的原因（依機率）先看 輸出持續振盪有效 COUT 不足（DC bias）、ESR 不在範圍、CFF 不當、輸入源阻抗高振盪 輸出週期性掉電再恢復熱關機循環、hiccup 限流、UVLO 反覆觸發熱、啟動 上電後沒有輸出EN 未拉高、UVLO 未過、foldback 卡住、預偏壓、OTP 設定錯誤啟動 上電輸出過衝軟啟動太快、迴路相位裕度不足、預偏壓、EA 飽和恢復過衝下衝 負載跳變時下衝太大COUT 不足、頻寬不足、輕載偏壓太低、PFM 模式反應慢過衝下衝 漣波 /","g":"issues","lv":1},{"p":"issues.html","a":"oscillation","t":"振盪","s":"現象可能原因怎麼查對策 LDO 輸出持續正弦振盪（數十 kHz–數 MHz）有效電容低於最小值；MLCC DC bias、溫度、0402 小封裝查電容規格的 DC bias 曲線；換大一號封裝或並聯一顆看是否消失選額定電壓較高、封裝較大的電容；確認最差情況有效容值 舊型 LDO 換陶瓷電容後振盪該 LDO 需要 ESR 零點才穩定規格書的 ESR 穩定區域圖串聯 0.2–1 Ω 小電阻、改用鉭電容，或換成支援陶瓷電容的 LDO 只在輕載或只在重載振盪輸出極點隨負載移動，某段負","g":"issues","lv":1},{"p":"issues.html","a":"startup","t":"啟動失敗與啟動異常","s":"現象可能原因怎麼查對策 完全沒有輸出EN 浮接或門檻未達；VIN 未過 UVLO；PMIC 時序在等某路 PG量 EN、VIN（在 IC 腳上）；讀故障暫存器EN 上拉 / 分壓；確認時序設定 輸出停在很低的電壓折返限流 + 重載或大電容負載；負載本身在低壓時吸大電流空載啟動是否正常負載延後開啟、降低 COUT、選定電流限流的 IC 反覆啟動、掉電電池 / 適配器內阻大，啟動湧入電流把 VIN 拉到 UVLO 以下同時量 VIN 與 VOUT加長軟啟動、加大輸入電容、提高 U","g":"issues","lv":1},{"p":"issues.html","a":"overshoot","t":"過衝與下衝","s":"現象可能原因對策 上電過衝軟啟動太快；EA 在啟動時飽和，恢復時超調；相位裕度不足加大軟啟動電容；確認穩定度 負載上升時下衝大COUT 不足；迴路頻寬低；PFM 模式需要時間切回 PWM增加電容（注意 DC bias）、強制 PWM、調整補償 負載卸載時過衝大LDO 傳輸元件關不快；Buck 不能吸電流（DCM / PFM）加大電容、加最小負載、FPWM、主動下拉 從壓差狀態恢復時過衝VIN 從低於 VOUT 回升時，EA 已飽和、傳輸元件全開選擇有壓差恢復控制的 LDO；加","g":"issues","lv":1},{"p":"issues.html","a":"thermal-shutdown","t":"過熱與熱關機","s":"症狀：輸出每隔數十 ms 到數秒掉電再恢復，晶片表面燙手，降低負載或 VIN 後消失。 先算：PD = (VIN − VOUT)·IOUT；用實際板子的熱阻估 TJ，常常一算就知道超過了。 常見原因： VIN 比設計值高（例如適配器 12 V 而非 5 V）。 散熱墊沒焊好、空洞過多（X-ray 檢查）、熱過孔數量不足。 2 層板、銅箔被切割，實際 θJA 遠高於規格書。 迴路振盪造成額外損失。 輸出短路或負載異常，限流狀態下 V","g":"issues","lv":1},{"p":"issues.html","a":"noise-ripple","t":"雜訊與漣波","s":"現象可能原因對策 Buck 輸出看到數百 mV 尖峰示波器長接地線拾取（量測假象）；或 ESL、佈局接地彈簧、量在電容兩端；加小容值高頻電容 LDO 後級還是看得到 Buck 漣波LDO 在切換頻率的 PSRR 不足；壓差太小；佈局把 SW 雜訊耦合到 LDO 輸出提高壓差裕度、在 LDO 前加 RC / LC、選高頻 PSRR 較好的 LDO 輕載時漣波變大、頻率變低PFM / 跳脈衝模式強制 PWM，或接受較低效率 ADC / 音訊有 1/f 或寬頻雜訊LDO 雜訊太高、","g":"issues","lv":1},{"p":"issues.html","a":"efficiency","t":"效率不如預期","s":"量測：電壓有沒有在 IC 接腳用四線量？電流表的分流電阻與線材壓降有沒有算進 PIN？ 電感：DCR 過高、飽和、交流損失；換規格書推薦電感比較。 輕載：是否在 FPWM 模式（輕載效率很低是正常的）。 頻率：外部設定頻率比預期高，切換損失增加。 體二極體導通：死區太長或外部低側 MOSFET 不合適。 熱：高溫時 RDS(on) 上升，效率下降，形成正回授。","g":"issues","lv":1},{"p":"issues.html","a":"reverse-current","t":"反灌與漏電","s":"關機後輸出仍有電壓：其他電源經 I/O 的 ESD 二極體灌到這一軌；或負載中有儲能元件。關斷時打開主動放電，或在系統時序中避免。 LDO 輸入斷電、輸出有電池或大電容：PMOS 體二極體讓電流從輸出流回輸入，可能損壞 LDO 或讓前級異常。選擇有反向電流保護的 LDO，或串聯二極體 / 理想二極體。 待機電流超標：EN 腳浮接導致部分開啟、上拉電阻、PG 上拉、分壓電阻的漏電、高溫漏電；逐一斷開量測。 PMIC 未上電時被 I²C 匯流排上拉供電：數位腳的 ESD 二極體讓","g":"issues","lv":1},{"p":"issues.html","a":"emi-issues","t":"EMI 超標","s":"傳導 EMI（150 kHz–108 MHz）：主要是切換頻率與諧波透過輸入線傳出。加大輸入濾波、展頻、改變頻率。 輻射 EMI（30 MHz 以上）：熱迴路面積與 SW 振鈴。縮小熱迴路、輸入加小電容（0402 / 0201）、BOOT 串電阻、加 RC 緩衝（snubber）。 近場掃描先找出熱點，比直接在暗室裡試錯快得多。 電纜與外殼：輸出長線也是天線；共模扼流圈、接地方式有時比改 IC 參數更有效。","g":"issues","lv":1},{"p":"issues.html","a":"design-issues","t":"設計類問題（晶片端）","s":"問題症狀根因預防 基板注入重載時 ADC 讀值異常、比較器誤觸發、偶發重置SW 節點低於地時少數載子注入保護環、DTI、縮短死區、佈局隔離 啟動電路失效極少數上電沒有輸出，重新上電恢復帶隙或偏壓電路有零電流穩態，啟動電路在某些角落無法推出啟動電路全角落模擬、VIN 斜率掃描 模式切換突波PFM ↔ PWM 切換時輸出跳動兩個模式的偏壓點不連續切換時預先設定 EA 狀態、遲滯 OTP 讀取裕度不足高溫或低電壓時讀錯配置，輸出電壓或時序錯誤OTP 感測放大器裕度不足、熔絲再生長讀","g":"issues","lv":1},{"p":"issues.html","a":"process-issues","t":"製程與封裝類問題","s":"問題症狀根因怎麼抓 封裝應力偏移FT 輸出電壓平均值比 CP 偏移，或隨塑封料批次變化塑封收縮應力透過壓阻效應影響帶隙與電阻CP / FT 配對分析、封裝後修調 回焊後參數漂移客戶上件後電壓精度變差回焊熱應力、吸濕後應力改變預處理 + 回焊後量測 熔絲再生長出貨後數月修調值改變熔絲未完全燒斷，經電遷移或高溫重新導通燒錄後電阻門檻、HTSL 後複測 分層 / 爆米花回焊後開路、漏電、參數異常吸濕超過 MSL 規定C-SAM 超音波掃描 銅線腐蝕高溫高濕後開路塑封料含鹵素 / 硫","g":"issues","lv":1},{"p":"issues.html","a":"test-issues","t":"測試類問題","s":"問題症狀根因對策 Socket 磨耗某參數分佈慢慢偏移、良率下降、重測回收率高接觸電阻上升Golden unit 每班檢查、使用次數管控、Kelvin 測試機間差異某台測試機良率系統性偏低校正、load board、繼電器機台相關性、定期校驗 Guard band 不足出貨品在客戶端量到超規未涵蓋測試誤差與溫度差依 GR&R 與溫度相關性設定 測試漏網客戶端功能失效但 FT 全過測試涵蓋率不足、只測常溫、穩定時間不夠失效分析後補測試項目，見客訴 · 漏網案例 過度剔除（ove","g":"issues","lv":1},{"p":"issues.html","a":"debug-tips","t":"量測與除錯技巧","s":"確認條件：VIN（在 IC 腳上量）、負載、溫度、EN、外部元件實際值，與規格書條件比較。 正確量測：示波器用接地彈簧或同軸量測；頻寬限制 20 MHz 看漣波，全頻寬看尖峰；電流探棒看電感電流。 同時看多條訊號：VIN、VOUT、SW、IL、EN、PG 一起量，才能分辨「誰先動」。 交換法（ABA swap）：把疑似不良的 IC 換到正常板，正常 IC 換到問題板；問題跟著 IC 走才是晶片問題，跟著板子走就是應用問題。 改一個變數：換電容、加負載、改溫度，每次只改一個。 ","g":"issues","lv":1},{"p":"complaints.html","a":"flow","t":"處理流程與時限","s":"受理與確認（24 小時內）：回覆收到、建立客訴編號，指定負責人。 初步圍堵（24–72 小時）：評估是否需要凍結庫存、篩選在途品、通知同批次的其他客戶。 收集資訊：失效率、批號 / 日期碼、使用條件、失效模式、照片與波形（見要問的資訊）。 取得樣品：失效品與同批良品，以及失效板（若可能）。要求客戶不要再通電試修。 失效驗證：在 ATE 與實驗室重現失效。無法重現就是 NTF，要回頭看應用條件。 失效分析（FA）：由非破壞到破壞，找出物理失效位置與機制（見FA 流程）。 根因與","g":"complaints","lv":1},{"p":"complaints.html","a":"info","t":"要向客戶收集的資訊","s":"類別問題 識別完整料號、打印（日期碼、批號）、購買管道（原廠、代理、現貨市場） 數量失效數 / 使用總數、失效在哪個階段（進料檢驗、SMT 後、功能測試、老化、出貨後、現場） 失效模式無輸出、輸出偏移、振盪、過熱、短路、漏電、間歇性？是否可恢復？ 應用條件原理圖、VIN 來源與範圍、負載、輸入輸出電容實際料號、佈局、環境溫度 變化最近是否改了設計、換了電容 / 電感 / 適配器供應商、換了 SMT 廠或回焊曲線、換了 IC 批次 事件失效前有沒有熱插拔、ESD 測試、雷擊、短","g":"complaints","lv":1},{"p":"complaints.html","a":"fa","t":"失效分析流程","s":"外觀檢查：光學顯微鏡看封裝破裂、燒焦、腳位損傷、焊錫殘留、打印是否正確（仿冒品檢查）。 X-ray：打線斷裂、偏移、焊錫空洞、晶片破裂。 C-SAM 超音波掃描：封裝內部分層、空洞。 電性驗證：ATE 完整測試程式、實驗室在客戶條件下重現；比較同批良品。 腳對腳 I-V 曲線（curve trace）：找出哪兩支腳之間短路、漏電或開路，與良品比較。 開封（decap）：化學或雷射去除塑封，露出晶片。 熱點定位：EMMI（光發射）、OBIRCH（雷射加熱電阻變化）、鎖相熱成像，","g":"complaints","lv":1},{"p":"complaints.html","a":"classification","t":"失效分類","s":"分類典型 FA 發現責任與方向 EOS 電性過應力大面積熔融金屬、燒穿的功率元件、封裝燒焦多為應用端瞬態；要找出能量來源 ESDESD 結構或輸入級的微小燒熔點產線靜電防護、系統級 ESD 設計 NTF 未發現異常ATE 與實驗室全部正常回到應用條件、焊接、板子、量測方法 晶圓製程缺陷氧化層缺陷、微粒、金屬短路晶圓廠，評估同批風險 封裝缺陷打線、分層、黏晶空洞、異物封裝廠 測試漏網失效可在 ATE 以特定條件重現，但量產程式未涵蓋測試工程，補測試項目 設計問題在特定條件下可重","g":"complaints","lv":1},{"p":"complaints.html","a":"eight-d","t":"8D 報告","s":"步驟內容常見問題 D0 準備判斷是否需要 8D、緊急應變 D1 團隊跨部門小組：品質、產品、測試、設計、應用、製造只有品質部門自己寫 D2 問題描述用 5W2H 描述：什麼、哪裡、何時、多少、怎麼發現描述太模糊，例如「IC 不良」 D3 圍堵隔離庫存、篩選、替代出貨，並驗證圍堵有效只寫「加強檢驗」 D4 根因發生根因（為什麼會產生）與流出根因（為什麼沒被抓到）都要找只找發生原因，忽略流出原因 D5 永久對策針對兩種根因各自的對策對策是「教育訓練」 D6 實施與驗證導入並以數據","g":"complaints","lv":1},{"p":"complaints.html","a":"tools","t":"根因分析工具","s":"5 Why：連續追問「為什麼」，直到找到可以改變的系統原因，而不是停在「操作員疏失」。 魚骨圖（石川圖）：從人、機、料、法、環、測（6M）列出可能原因，避免遺漏。 Is / Is-not 分析：哪些批次、哪些客戶、哪些條件有問題？哪些沒有？差異點就是線索。 故障樹（FTA）：從頂端失效事件往下展開所有可能路徑，逐一以數據排除。 資料分析：把失效品的批號對回 CP / FT 資料，看它們在分佈中的位置；常會發現失效品原本就是邊緣值或 PAT 離群值。","g":"complaints","lv":1},{"p":"complaints.html","a":"cases","t":"典型客訴案例","s":"","g":"complaints","lv":1},{"p":"complaints.html","a":"c-eos","t":"熱插拔尖峰燒毀 Buck 輸入","s":"EOS消費性 · 12 V 適配器 現象產品在使用者端偶發無法開機，退回的 Buck 晶片 VIN 對地短路，失效率約 0.1%。 分析FA 看到高側開關大面積熔融，屬典型 EOS。在客戶板上以長線插拔 12 V 適配器，量到 VIN 尖峰 23 V，超過 IC 絕對最大額定 20 V。 根因輸入只有陶瓷電容，與適配器線材電感形成低阻尼 LC 諧振；新設計拿掉了原本的電解電容以節省成本。 對策輸入加 TVS 與電解電容阻尼；長期改用 28 V 耐壓的料號。應用文件加入熱插拔說","g":"complaints","lv":2},{"p":"complaints.html","a":"c-mlcc","t":"換了電容供應商，LDO 開始振盪","s":"應用工業 · 3.3 V LDO 現象量產兩年沒問題，某月起產線功能測試出現 3% 的 ADC 讀值異常，客戶認為 LDO 批次有問題。 分析退回的 LDO 全部通過測試（NTF）。在失效板上量到 LDO 輸出 400 kHz 振盪。交換法：好 IC 放到壞板仍振盪。 根因客戶的採購換了一家 0402、6.3 V 的 2.2 µF MLCC，在 3.3 V 偏壓下只剩約 0.8 µF，低於 LDO 最小穩定電容 1 µF。部分板子再加上電容公差就振盪。 對策改用 0603、1","g":"complaints","lv":2},{"p":"complaints.html","a":"c-otp","t":"OTP 設定錯誤，輸出電壓不對","s":"生產PMIC · 料號配置 現象客戶收到一卷 PMIC，其中某一路輸出是 1.8 V 而非 1.2 V，造成 SoC 損壞。 分析讀出 OTP 內容，發現是同一顆晶片的另一個料號的設定。追溯到 FT 換料號時，測試程式切換後燒錄檔沒有同步更新。 根因發生：料號切換流程靠人工確認。流出：FT 只驗證「燒錄成功」，沒有比對燒錄內容與料號的對應。 對策測試程式依料號自動載入燒錄檔；燒錄後讀回 OTP 並與料號主檔比對 CRC；同期批次全部回收篩選。 教訓可配置晶片的風險在「設定管理","g":"complaints","lv":2},{"p":"complaints.html","a":"c-escape","t":"低溫 UVLO 門檻漏網","s":"測試車用 · LDO 現象冬季冷啟動時，少數車輛的 ECU 重置。退回的 LDO 在常溫正常。 分析在 −40 °C 量測，失效品的 UVLO 上升門檻比規格高 150 mV；同批其他晶片正常。CP 資料顯示失效品在常溫已是分佈的極端值。 根因發生：晶圓局部製程偏移造成 UVLO 比較器的溫度係數異常。流出：FT 只測常溫與高溫，且 UVLO 參數沒有納入 PAT。 對策增加冷測，或以常溫值加入 PAT 動態界限剔除離群值；檢討其他溫度敏感參數的測試溫度覆蓋。 教訓離群值常是","g":"complaints","lv":2},{"p":"complaints.html","a":"c-delam","t":"違反 MSL 造成分層","s":"封裝消費性 · QFN PMIC 現象SMT 後功能測試失效率突然上升到 0.5%，失效為輸出電壓偏移與間歇性開路。 分析C-SAM 顯示晶片表面與塑封料間分層；未上件的同批料正常。追查發現該批料拆封後在產線放置超過兩週。 根因MSL 3 元件超過車間壽命（168 小時）未烘烤，回焊時吸收的水氣汽化造成分層，拉扯打線並改變晶片應力。 對策客戶導入濕敏元件管制（拆封時間紀錄、乾燥櫃、超時烘烤）。供應商端在包裝標示加強提醒。 教訓不是所有失效都發生在晶片廠內；客戶的製程管制也是可","g":"complaints","lv":2},{"p":"complaints.html","a":"c-ntf","t":"退回品全部正常：焊接問題","s":"NTF穿戴 · WLCSP LDO 現象產品經落摔測試後部分輸出異常，客戶退回 20 顆 LDO 要求分析。 分析20 顆全部通過 ATE 與實驗室測試。要求客戶提供失效板，截面分析發現 WLCSP 焊球與 PCB 焊墊之間有裂縫。 根因PCB 焊墊設計與底部填充（underfill）未依建議，落摔時應力集中在焊點。 對策依建議修正焊墊尺寸並加 underfill；後續 NTF 案件標準流程要求附失效板。 教訓NTF 不等於「沒問題」；把 IC 拆下來時可能剛好把證據也毀了。","g":"complaints","lv":2},{"p":"complaints.html","a":"c-pcn","t":"未通知的塑封料變更","s":"變更工業 · 精密 LDO 現象客戶的高溫高濕老化測試中，LDO 輸出電壓漂移 0.8%，超過系統允許的 0.5%；舊批次沒有這個現象。 分析比較新舊批次，封裝廠為了供貨更換了同等級的塑封料，內部判定「不影響規格」而未發 PCN。新塑封料吸濕後應力變化較大。 根因變更管理的影響評估只看常溫電性，未考慮濕度應力對精密參數的影響。 對策回復原塑封料；變更管理規範中，凡影響晶片應力的材料變更都需做溫濕度後漂移驗證並通知客戶。 教訓「不影響規格」要用驗證資料證明；有疑慮時就發 PCN","g":"complaints","lv":2},{"p":"complaints.html","a":"c-esd","t":"系統 ESD 測試打壞 IC","s":"ESD消費性 · USB 端口電源開關 現象客戶在 IEC 61000-4-2 ±8 kV 接觸放電測試後，負載開關損壞；客戶認為規格書寫 ±2 kV HBM 不夠。 分析FA 看到輸入 ESD 結構熔毀。IC 的 HBM 與 CDM 等級符合規格；系統級放電的能量與電流遠大於 HBM。 根因USB 端口沒有外部 TVS，系統 ESD 能量全部進入 IC。 對策端口加 TVS 並靠近連接器；應用文件說明 HBM 與系統級 ESD 的差異。 教訓元件級與系統級 ESD 是不同的","g":"complaints","lv":2},{"p":"complaints.html","a":"c-counterfeit","t":"現貨市場買到的仿冒品","s":"仿冒缺貨期間 · LDO 現象缺貨期間客戶從非授權管道補貨，新批次 IQ 偏高、壓差大，部分無法穩定。 分析打印字型與原廠不同、日期碼與批號對不上原廠紀錄；開封後晶片標識屬於另一家廠商的低階產品。 根因非授權管道的重新打印仿冒品。 對策客戶只向原廠或授權代理採購；原廠提供批號驗證服務。 教訓處理客訴的第一步之一是確認購買管道；不是原廠出的貨，就不是原廠的品質問題，但仍要協助客戶辨識。","g":"complaints","lv":2},{"p":"complaints.html","a":"c-foldback","t":"折返限流讓 LDO 無法啟動","s":"設計工業 · FPGA 輔助電源 現象部分板子上電後輸出停在 0.6 V，無法升到 2.5 V；重新上電有時可以。 分析負載的 FPGA 輔助電源在低電壓時就開始吸大電流，LDO 的折返限流在低 VOUT 時只允許 200 mA，無法同時供應負載與對 100 µF 輸出電容充電。 根因應用條件與折返限流特性不相容，規格書雖有折返曲線但應用說明未提醒。 對策改用定電流限流的料號，或以 PG 延後啟動負載；規格書應用章節加入啟動注意事項。 教訓保護電路的行為也是規格的一部分，要寫","g":"complaints","lv":2},{"p":"complaints.html","a":"communication","t":"與客戶溝通","s":"先回應，再分析：24 小時內給一份初步回覆，說明已收到、接下來的步驟與時程，比沉默三天後給完整報告更好。 用數據說話：「IC 沒問題」要附上測試資料、交換法結果、量測波形，而不是只給結論。 不要急著歸責：EOS 或應用問題的結論，也要提出具體的能量來源或條件，並提供改善建議。客戶需要的是解決方案，不是責任判定。 階段性報告：長時間的 FA 每隔幾天更新一次進度。 一個窗口：客戶對口統一，避免不同部門給出不一致的說法。 結案後追蹤：確認對策在客戶端有效，失效率回到基準。","g":"complaints","lv":1},{"p":"complaints.html","a":"metrics","t":"品質指標","s":"指標定義典型目標 DPPM客戶端確認不良數 / 出貨數 × 106消費性 < 10–50；車用 < 1 初回應時間收到客訴到第一次回覆< 24 小時 8D 週期收到客訴到 8D 結案< 30 天 FA 週期收到樣品到 FA 報告1–3 週 再發率同一根因再次發生的比例0 RMA退貨授權的數量與原因分佈依原因追蹤趨勢","g":"complaints","lv":1},{"p":"complaints.html","a":"glossary","t":"名詞解釋","s":"","g":"complaints","lv":1},{"p":"complaints.html","a":"glossary","t":"8D","s":"Eight Disciplines，八個步驟的問題解決與報告格式。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"FA","s":"Failure Analysis，失效分析。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"NTF / NFF","s":"No Trouble Found / No Fault Found，未發現異常。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"RMA","s":"Return Material Authorization，退貨授權。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"C-SAM","s":"C-mode Scanning Acoustic Microscopy，超音波掃描顯微鏡，看封裝分層。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"EMMI","s":"Emission Microscopy，偵測缺陷處的微弱光發射。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"OBIRCH","s":"Optical Beam Induced Resistance Change，雷射加熱造成的電阻變化定位。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"FIB","s":"Focused Ion Beam，聚焦離子束，用於截面與電路修改。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"Containment","s":"圍堵，防止可疑品繼續流到客戶端的短期措施。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"Escape","s":"流出 / 漏網，缺陷品通過測試流到客戶端。","g":"complaints","lv":3},{"p":"complaints.html","a":"glossary","t":"FMEA","s":"Failure Mode and Effects Analysis，失效模式與影響分析。","g":"complaints","lv":3},{"p":"roles.html","a":"overview","t":"總覽","s":"職位一句話最相關章節 類比設計設計 LDO、DC-DC、參考電壓、保護電路，對規格與穩定度負責架構、設計、製程 類比佈局把電路畫成光罩，處理匹配、功率路徑、隔離與 ESD製程、設計 系統 / 數位設計PMIC 時序器、介面、OTP 控制、故障處理與功能安全設計（PMIC 數位）、測試（DFT） 應用工程 AE / FAE幫客戶把電源設計對，處理振盪、熱、EMI 與客訴的應用端分析應用、常見問題、客訴 產品工程 PE負責量產良率、修調、Cpk、成本與變更生產、測試 測試工程 T","g":"roles","lv":1},{"p":"roles.html","a":"analog","t":"類比設計","s":"類比設計工程師從規格出發選擇架構（PMOS / NMOS LDO、控制模式），設計誤差放大器、補償、參考、保護與偏壓電路，跑 PVT 與蒙地卡羅模擬，並在晶片回來後主導特性化與除錯。資深設計者也會參與規格定義與競品分析。 必讀：LDO 方塊圖、LDO 迴路、PSRR、帶隙參考、保護電路、DC-DC 控制模式、設計驗證 工具：LDO 穩定度、PSRR、負載暫態","g":"roles","lv":1},{"p":"roles.html","a":"analog-q","t":"面試常見問題","s":"PMOS LDO 的主極點在哪裡？負載變化時極點怎麼移動？為什麼輕載通常比較穩定？ 為什麼舊的 LDO 用陶瓷電容會振盪？內部補償怎麼解決？ PSRR 在低頻、中頻、高頻各由什麼決定？怎麼改善 1 MHz 的 PSRR？ 畫出帶隙參考，說明 PTAT 與 CTAT 怎麼抵消；運放偏移對輸出的影響有多大？ 峰值電流模式為什麼需要斜率補償？ 折返限流的優缺點？什麼情況下會造成啟動失敗？","g":"roles","lv":2},{"p":"roles.html","a":"layout","t":"類比佈局","s":"佈局工程師把電路變成實體：大面積功率元件的金屬與 via 配置、精密元件的共質心匹配、敏感電路與功率級的隔離、ESD 與保護環、電遷移與壓降檢查。佈局品質直接影響 RDS(on)、精度、雜訊與可靠度。 必讀：LDMOS、隔離與寄生、基板注入、厚金屬與電遷移、匹配與應力、ESD 與 latch-up","g":"roles","lv":1},{"p":"roles.html","a":"layout-q","t":"面試常見問題","s":"共質心佈局在抵消什麼？為什麼要加虛設元件？ 功率元件的金屬怎麼分配才能讓電流均勻？via 數量怎麼決定？ 保護環的作用是什麼？N+ 與 P+ 保護環分別收集什麼載子？ 精密電阻要放在晶片哪裡？為什麼不放在焊墊下方？","g":"roles","lv":2},{"p":"roles.html","a":"digital","t":"系統 / 數位設計","s":"PMIC 的數位部分包括上電時序器、I²C / SPMI / PMBus 介面、暫存器、OTP 控制、故障狀態機、看門狗與功能安全機制。數位設計師也要和類比設計一起做混合訊號驗證，並和測試工程定義 DFT。 必讀：PMIC 整合、PMIC 的數位部分、可測試性設計、功能安全測試、上電時序","g":"roles","lv":1},{"p":"roles.html","a":"digital-q","t":"面試常見問題","s":"設計一個四路電源的上電時序器，需要哪些狀態？斷電時序怎麼處理？ OTP 讀取錯誤要怎麼偵測？燒錄流程如何防呆？ 故障發生時應該只關一路、全部關，還是 hiccup？依什麼決定？ 測試模式進入序列要怎麼設計才不會在客戶系統中被誤觸？","g":"roles","lv":2},{"p":"roles.html","a":"ae","t":"應用工程 AE / FAE","s":"AE 寫應用文件與參考設計、做評估板與特性化資料；FAE 在客戶端支援設計導入、審查原理圖與佈局、處理現場問題。客訴時，AE / FAE 通常是第一個判斷「是不是應用問題」的人。 必讀：電源樹、電容選擇、熱設計、佈局、EMI、熱插拔、常見問題全篇、客訴資訊收集 工具：MLCC DC bias、壓差與熱、Buck 漣波、PSRR","g":"roles","lv":1},{"p":"roles.html","a":"ae-q","t":"面試常見問題","s":"客戶說 LDO 振盪，你會先問哪些問題？現場會怎麼量？ 10 µF / 0603 / 6.3 V 的電容在 3.3 V 下大概剩多少？怎麼查？ 5 V 降 3.3 V、500 mA，SOT-23 可以嗎？怎麼算？ Buck 佈局最重要的三件事是什麼？ 熱插拔為什麼會出現接近兩倍輸入電壓的尖峰？怎麼解？ 怎麼判斷漣波是真的，還是探棒量測假象？","g":"roles","lv":2},{"p":"roles.html","a":"pe","t":"產品工程 PE","s":"PE 是產品量產後的「負責人」：監控 CP / FT 良率與修調碼分佈，主導良率改善、Cpk 提升、測試成本降低；處理製程或封裝變更的評估與 PCN；在客訴時提供批次資料與風險評估。 必讀：CP 與修調、良率、Cpk 與 SPC、PAT、追溯、PCN、相關性 工具：修調與良率","g":"roles","lv":1},{"p":"roles.html","a":"pe-q","t":"面試常見問題","s":"Cpk 1.33 和 1.67 各代表多少超規率？修調後的均勻分佈為什麼不適合直接算 Cpk？ 某週良率掉了 2%，你會怎麼追？要看哪些資料？ 修調碼分佈開始往一邊偏，代表什麼？ CP 修調後 FT 平均偏移 +0.3%，怎麼處理？ 封裝廠想把金線改成銅線，你要評估什麼？","g":"roles","lv":2},{"p":"roles.html","a":"te","t":"測試工程 TE","s":"TE 開發與維護 ATE 測試程式、load board 與探針卡 / socket，定義測試極限與 guard band，優化測試時間與多站效率，並負責機台間與 CP / FT / 實驗室的相關性。 必讀：LDO 參數怎麼量、ATE、DFT、Kelvin 量測、相關性與 GR&R、測試類問題","g":"roles","lv":1},{"p":"roles.html","a":"te-q","t":"面試常見問題","s":"怎麼在 CP 量一顆 30 mΩ 的開關？接觸電阻怎麼排除？ LDO 輸出接大電容時，測試時間要怎麼縮短？ GR&R 的意義是什麼？多少算可接受？ 良率低但重測大部分通過，可能是什麼原因？ 只測常溫的風險是什麼？哪些參數一定要測冷熱？","g":"roles","lv":2},{"p":"roles.html","a":"pi","t":"製程整合 / 元件工程","s":"在 IDM 或晶圓廠，負責 BCD 平台的元件（LDMOS、BJT、電阻、電容、OTP）開發與量產穩定；在 fabless，則是晶圓廠窗口，負責 WAT 監控、製程變更評估與良率問題的晶圓端調查。 必讀：製程全章、WAT、製程與封裝類問題","g":"roles","lv":1},{"p":"roles.html","a":"pi-q","t":"面試常見問題","s":"LDMOS 的 Rsp 與崩潰電壓怎麼取捨？RESURF 是什麼？ LDMOS 的熱載子退化發生在哪裡？怎麼驗證？ 接面隔離、DTI、SOI 的優缺點？ 高阻多晶矽電阻在封裝後漂移，可能的原因？","g":"roles","lv":2},{"p":"roles.html","a":"qra","t":"品質與可靠度 QRA","s":"QRA 規劃與執行可靠度驗證、管理 PCN 與變更、維持出貨品質指標，並主導客訴處理與 8D 報告。車用產品還要負責 PPAP、IATF 16949 稽核與功能安全文件。 必讀：AEC-Q100、ESD 與 latch-up、PAT、PCN、客訴流程、8D、案例","g":"roles","lv":1},{"p":"roles.html","a":"qra-q","t":"面試常見問題","s":"AEC-Q100 的主要測試項目與樣本數？Grade 1 與 Grade 0 的差別？ HBM ±2 kV 的 IC 能不能承受系統級 ±8 kV？為什麼？ 8D 的 D4 為什麼要同時找發生與流出根因？ 客戶退回的晶片 ATE 全部通過，接下來怎麼做？ 什麼樣的變更需要發 PCN？","g":"roles","lv":2},{"p":"roles.html","a":"fa","t":"失效分析 FA","s":"FA 工程師負責退回品的非破壞與破壞性分析：X-ray、C-SAM、曲線量測、開封、熱點定位、去層、FIB 與 SEM。好的 FA 不只找到「哪裡燒了」，還要能推論能量從哪裡來、為什麼在那裡。 必讀：FA 流程、失效分類、LDMOS、隔離與寄生","g":"roles","lv":1},{"p":"roles.html","a":"fa-q","t":"面試常見問題","s":"EOS 與 ESD 的 FA 特徵差在哪裡？ 為什麼要先做非破壞分析？順序怎麼排？ EMMI 與 OBIRCH 各適合找什麼缺陷？ C-SAM 看到分層，怎麼判斷是不是失效原因？ 職稱與分工依公司規模與型態（IDM、fabless、模組廠）而不同，這裡是通用描述。","g":"roles","lv":2},{"p":"lab.html","a":"bode","t":"LDO 穩定度：Bode 圖與 ESR 穩定窗口","s":"相位裕度 phase margin 交越頻率 輸出極點 ESR 零點 tunnel of death 陶瓷電容 鉭電容 內部補償 最小電容 振盪","g":"lab","lv":1},{"p":"lab.html","a":"psrr","t":"PSRR 頻率響應模擬","s":"電源抑制比 壓差裕度 dropout Buck 漣波 切換頻率 後級濾波 PMOS NMOS","g":"lab","lv":1},{"p":"lab.html","a":"transient","t":"負載暫態模擬","s":"load transient 下衝 過衝 ESR 迴路頻寬 相位裕度 振鈴 迴轉率 slew 負載調節","g":"lab","lv":1},{"p":"lab.html","a":"thermal","t":"壓差、功耗與接面溫度","s":"dropout 熱 θJA 封裝 SOT-23 DFN QFN 熱關機 TSD 打嗝 hiccup 效率","g":"lab","lv":1},{"p":"lab.html","a":"buck","t":"Buck 電感漣波、輸出漣波與效率","s":"duty cycle 漣波電流 飽和電流 Isat CCM DCM PFM FPWM t_ON,min 效率曲線","g":"lab","lv":1},{"p":"lab.html","a":"mlcc","t":"MLCC DC bias 有效電容","s":"陶瓷電容 直流偏壓 X5R X7R Y5V 尺寸 0402 0603 額定電壓 溫度 老化 容差","g":"lab","lv":1},{"p":"lab.html","a":"trim","t":"修調與良率 / Cpk 模擬","s":"trim 修調碼 LSB 位元數 封裝偏移 預補償 CP FT 良率 Cpk 蒙地卡羅","g":"lab","lv":1},{"p":"quiz.html","a":"","t":"電源 IC 測驗","s":"quiz 題庫 自我檢查 架構 製程 設計 生產 測試 應用 客訴","g":"quiz","lv":1}];
